//! nt brand: Material 3 roles generated by `frameworks/design` (Material Color Utilities from
//! `frameworks/design/design.toml`). nt currently uses Fluent and WinUI 3 for controls; this crate only
//! provides the brand colors, shapes and durations, as `u32` RGBA (`0xRRGGBBFF`).
#![no_std]
#![forbid(unsafe_code)]

include!(concat!(env!("CARGO_MANIFEST_DIR"), "/../../../../../packages/design/tokens/tokens.rs"));

/// Components `[r, g, b, a]` in `0.0..=1.0` (D3D12 clear color, `windows::UI::Color` after scaling).
pub const fn rgba_f32(c: u32) -> [f32; 4] {
    [
        ((c >> 24) & 0xFF) as f32 / 255.0,
        ((c >> 16) & 0xFF) as f32 / 255.0,
        ((c >> 8) & 0xFF) as f32 / 255.0,
        (c & 0xFF) as f32 / 255.0,
    ]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn primaire_de_marque() {
        assert_eq!(md::light::PRIMARY, 0x006492FF);
        assert_eq!(md::dark::PRIMARY, 0x8BCEFFFF);
        assert_eq!(rgba_f32(md::light::ON_PRIMARY), [1.0, 1.0, 1.0, 1.0]);
    }
}
